.knowhowsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2733;
    background: linear-gradient(160deg, #eef1f4 0%, #e4e8ed 100%);
    border-radius: 18px;
}

.knowhowsim-container * {
    box-sizing: border-box;
}

.knowhowsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1b2a3a 0%, #27384c 55%, #324a63 100%);
    color: #f1f5f9;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(27, 42, 58, 0.32);
    border-bottom: 4px solid #c0762f;
}

.knowhowsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.knowhowsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0c89a;
    background: rgba(192, 118, 47, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.knowhowsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d7dee6;
}

.knowhowsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3e52;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.knowhowsim-period-counter #currentDay,
.knowhowsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1b2a3a;
}

.knowhowsim-round-name {
    background: #d7e0e9;
    color: #1b2a3a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.knowhowsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4a18;
    background: #f6e3d2;
    padding: 4px 12px;
    border-radius: 999px;
}

.knowhowsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.knowhowsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d3dbe3;
    box-shadow: 0 4px 14px rgba(27, 42, 58, 0.06);
    border-top: 4px solid #324a63;
}

.knowhowsim-card-transfer { border-top-color: #1f6f8b; }
.knowhowsim-card-align { border-top-color: #5a4a9c; }
.knowhowsim-card-perf { border-top-color: #1d7a4d; }
.knowhowsim-card-retention { border-top-color: #c0762f; }

.knowhowsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #647689;
}

.knowhowsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1b2a3a;
}

.knowhowsim-card-transfer .knowhowsim-value { color: #1f6f8b; }
.knowhowsim-card-align .knowhowsim-value { color: #5a4a9c; }
.knowhowsim-card-perf .knowhowsim-value { color: #1d7a4d; }
.knowhowsim-card-retention .knowhowsim-value { color: #c0762f; }

.knowhowsim-sublabel {
    font-size: 0.75rem;
    color: #76889a;
    line-height: 1.35;
}

.knowhowsim-perf-fail .knowhowsim-value { color: #c0392b; }
.knowhowsim-perf-target .knowhowsim-value { color: #1d7a4d; }

.knowhowsim-retention-loss { border-top-color: #c0392b; }
.knowhowsim-retention-loss .knowhowsim-value { color: #c0392b; }

.knowhowsim-resource-bars {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 18px;
}

.knowhowsim-budget-bar,
.knowhowsim-days-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.9rem;
}

.knowhowsim-budget-bar {
    background: #1b2a3a;
    color: #e9eff5;
}

.knowhowsim-days-bar {
    background: #45342a;
    color: #f6e3d2;
}

.knowhowsim-budget-bar #budgetDisplay,
.knowhowsim-days-bar #daysDisplay {
    font-size: 1.02rem;
    letter-spacing: 0.3px;
}

.knowhowsim-budget-over #budgetDisplay,
.knowhowsim-days-over #daysDisplay {
    color: #ff9b8a;
}

.knowhowsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #324a63;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(27, 42, 58, 0.05);
}

.knowhowsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.knowhowsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1b2a3a;
    margin-bottom: 6px;
}

.knowhowsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34495e;
}

.knowhowsim-briefing-text strong { color: #1d7a4d; }
.knowhowsim-briefing-text em { color: #9a4a18; font-style: italic; }

.knowhowsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d3dbe3;
    box-shadow: 0 4px 14px rgba(27, 42, 58, 0.06);
}

.knowhowsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1b2a3a;
    border-bottom: 2px solid #e4e8ed;
    padding-bottom: 8px;
}

.knowhowsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #283b4d;
    margin: 14px 0 6px;
}

.knowhowsim-container select,
.knowhowsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b7c4d1;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f8fb;
    color: #1d2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.knowhowsim-container select:focus,
.knowhowsim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f6f8b;
    box-shadow: 0 0 0 3px rgba(31, 111, 139, 0.16);
}

.knowhowsim-container select option {
    background-color: #ffffff;
    color: #1d2733;
}

.knowhowsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f6f8b;
}

.knowhowsim-range-readout,
.knowhowsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1f6f8b;
    margin-top: 4px;
}

.knowhowsim-range-readout span:last-child,
.knowhowsim-alloc-readout span:nth-child(2) {
    color: #1d7a4d;
    font-weight: 800;
}

.knowhowsim-hint {
    font-size: 0.8rem;
    color: #76889a;
    margin-top: 4px;
    line-height: 1.4;
}

.knowhowsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.knowhowsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2f5f8;
    border: 1px solid #dde4eb;
    border-radius: 9px;
    padding: 8px 12px;
}

.knowhowsim-alloc-name {
    flex: 1;
    font-size: 0.86rem;
    font-weight: 600;
    color: #283b4d;
}

.knowhowsim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.knowhowsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.knowhowsim-container .btn-primary {
    background: linear-gradient(135deg, #1d7a4d 0%, #1f6f8b 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(29, 122, 77, 0.28);
}

.knowhowsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.knowhowsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b7c4d1;
    color: #647689;
}

.knowhowsim-coach {
    background: #1b2a3a;
    color: #e9eff5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(27, 42, 58, 0.24);
    border-left: 5px solid #c0762f;
}

.knowhowsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0c89a;
    margin-bottom: 8px;
}

.knowhowsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.knowhowsim-coach-body strong { color: #f3d3a6; }
.knowhowsim-coach-body em { color: #ffc1ad; font-style: italic; }

.knowhowsim-history,
.knowhowsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d3dbe3;
    box-shadow: 0 4px 14px rgba(27, 42, 58, 0.06);
}

.knowhowsim-history h3,
.knowhowsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1b2a3a;
}

.knowhowsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #283b4d;
}

.knowhowsim-container table#usfHistoryTable th {
    background: #e8edf2;
    color: #1b2a3a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d1dae3;
}

.knowhowsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f6;
}

.knowhowsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fb;
}

.knowhowsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .knowhowsim-container {
        padding: 14px;
    }
    .knowhowsim-header h1 {
        font-size: 1.7rem;
    }
    .knowhowsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .knowhowsim-value {
        font-size: 2rem;
    }
    .knowhowsim-clock {
        margin-left: 0;
    }
    .knowhowsim-period-counter {
        font-size: 0.88rem;
    }
    .knowhowsim-resource-bars {
        grid-template-columns: 1fr;
    }
    .knowhowsim-budget-bar,
    .knowhowsim-days-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .knowhowsim-alloc-row {
        flex-wrap: wrap;
    }
    .knowhowsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .knowhowsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

