(function() {
    'use strict';

    class KnowHowAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Transferring Know-How`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.BUDGET_CAP = 2.4;          // EUR 2.4M transfer budget HQ will fund (reported in EUR)
            this.BUDGET_MAX = 3.6;          // hard ceiling on what teams can over-commit (shopping error)
            this.DAYS_CAP = 600;            // seconded-engineer days available (4 engineers)
            this.START_TRANSFER = 12;
            this.START_ALIGN = 20;
            this.START_PERF = 15;
            this.START_ENGINEERS = 4;
            this.TARGET_PERF = 70;          // demonstrable 12-month convergence
            this.GROUP_PERF = 78;           // full convergence to group benchmarks — only the genuine ceiling run (perf 78) reaches it
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    transfer: this.START_TRANSFER,
                    align: this.START_ALIGN,
                    perf: this.START_PERF,
                    engineers: this.START_ENGINEERS,
                    budgetUsed: 0,
                    daysUsed: 0,
                    targetMissed: false,
                    overBudget: false,
                    overDays: false,
                    channelLost: false,
                    transferHistory: [this.START_TRANSFER],
                    alignHistory: [this.START_ALIGN],
                    perfHistory: [this.START_PERF],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING / neutral mix — NOT the textbook-correct play.
                state.decisions = {
                    nature: `explicit`,
                    barrier: `channel`,
                    focus: `spread`,
                    candour: 50,
                    inpatriate: 0.40,
                    jointteam: 0.40,
                    codification: 0.80,
                    digitaltwin: 0.80,
                    engineerDays: 300,
                    inpatCount: 3,
                    standard: `wholesale`,
                    absorptive: 0.20,
                    retention: `match`,
                    reintegration: 50,
                    milestones: `annual`,
                    logic: `financial`,
                    staffing: `optimistic`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const nat = document.getElementById(`natureInput`);
                const bar = document.getElementById(`barrierInput`);
                const foc = document.getElementById(`focusInput`);
                const can = document.getElementById(`candourInput`);
                if (nat) decisions.nature = nat.value;
                if (bar) decisions.barrier = bar.value;
                if (foc) decisions.focus = foc.value;
                if (can) decisions.candour = parseInt(can.value, 10);
                if (!Number.isFinite(decisions.candour) || decisions.candour < 0 || decisions.candour > 100) {
                    warn(`warn_candour_range`); return false;
                }
            } else if (round === 2) {
                const inp = document.getElementById(`inpatriateInput`);
                const jt = document.getElementById(`jointteamInput`);
                const cod = document.getElementById(`codificationInput`);
                const dt = document.getElementById(`digitaltwinInput`);
                const ed = document.getElementById(`engineerDaysInput`);
                const ic = document.getElementById(`inpatCountInput`);
                if (inp) decisions.inpatriate = parseFloat(inp.value);
                if (jt) decisions.jointteam = parseFloat(jt.value);
                if (cod) decisions.codification = parseFloat(cod.value);
                if (dt) decisions.digitaltwin = parseFloat(dt.value);
                if (ed) decisions.engineerDays = parseFloat(ed.value);
                if (ic) decisions.inpatCount = parseInt(ic.value, 10);
                const parts = [decisions.inpatriate, decisions.jointteam, decisions.codification, decisions.digitaltwin];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_budget_negative`); return false;
                }
                const total = Math.round((decisions.inpatriate + decisions.jointteam + decisions.codification + decisions.digitaltwin) * 100) / 100;
                // You may over-commit (the classic "mechanism shopping" error) up to a hard ceiling,
                // but over-spending the EUR 2.4M HQ will fund is penalised in scoring.
                if (total < 0.5) { warn(`warn_budget_low`); return false; }
                if (total > this.BUDGET_MAX + 0.001) { warn(`warn_budget_total`); return false; }
                if (!Number.isFinite(decisions.engineerDays) || decisions.engineerDays < 0) {
                    warn(`warn_days_negative`); return false;
                }
            } else if (round === 3) {
                const std = document.getElementById(`standardInput`);
                const abs = document.getElementById(`absorptiveInput`);
                const ret = document.getElementById(`retentionInput`);
                const rei = document.getElementById(`reintegrationInput`);
                if (std) decisions.standard = std.value;
                if (abs) decisions.absorptive = parseFloat(abs.value);
                if (ret) decisions.retention = ret.value;
                if (rei) decisions.reintegration = parseInt(rei.value, 10);
                if (!Number.isFinite(decisions.absorptive) || decisions.absorptive < 0) {
                    warn(`warn_absorptive_negative`); return false;
                }
                if (!Number.isFinite(decisions.reintegration) || decisions.reintegration < 0 || decisions.reintegration > 100) {
                    warn(`warn_reintegration_range`); return false;
                }
            } else if (round === 4) {
                const mi = document.getElementById(`milestonesInput`);
                const lo = document.getElementById(`logicInput`);
                const st = document.getElementById(`staffingInput`);
                const cv = document.getElementById(`convictionInput`);
                if (mi) decisions.milestones = mi.value;
                if (lo) decisions.logic = lo.value;
                if (st) decisions.staffing = st.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // transferDelta  = movement of genuinely absorbed tacit know-how (the channel quality)
            // alignDelta     = HQ-intent / family-local-fit alignment (Kiessling's second pillar)
            // engineerDelta  = change in seconded-engineer headcount (the fragile channel)
            // spend / days   = resource consumption against the EUR 2.4M and 600-day caps
            let transferDelta = 0, alignDelta = 0, engineerDelta = 0;
            let spend = 0, days = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: tacit-not-explicit + recipient/context barrier + EBITDA-weighted focus.
                if (d.nature === `tacit`) {
                    transferDelta += 14; alignDelta += 2; coachKey = `coach_r1_tacit`;
                } else if (d.nature === `explicit`) {
                    transferDelta -= 8; coachKey = `coach_r1_explicit`;
                } else if (d.nature === `effort`) {
                    transferDelta -= 9; coachKey = `coach_r1_effort`;
                } else { // willing -> blame & replace people
                    transferDelta -= 11; alignDelta -= 6; coachKey = `coach_r1_willing`;
                }

                if (d.barrier === `recipient`) {
                    transferDelta += 9; alignDelta += 4;
                    if (d.nature === `tacit`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.barrier === `source`) {
                    transferDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r1_source` : coachKey;
                } else if (d.barrier === `channel`) {
                    transferDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r1_channel` : coachKey;
                } else { // none
                    transferDelta -= 10; alignDelta -= 4; coachKey = `coach_r1_none`;
                }

                // EBITDA-weighted focus: lean/quality carries the gap; spreading evenly converges on nothing.
                if (d.focus === `quality`) { transferDelta += 7; }
                else if (d.focus === `aftersales`) { transferDelta += 1; }
                else { transferDelta -= 4; } // spread

                if (d.candour >= 60) { transferDelta += 5; }
                else if (d.candour <= 25) { transferDelta -= 6; coachKey = `coach_r1_lowcandour`; }

                summaryKey = (d.nature === `tacit` && d.barrier === `recipient` && d.focus === `quality`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose mechanisms: people-based move tacit know-how; documents move little.
                const peopleSpend = d.inpatriate + d.jointteam;     // tacit channels
                const docSpend = d.codification + d.digitaltwin;     // explicit / supporting
                const totalSpend = d.inpatriate + d.jointteam + d.codification + d.digitaltwin;
                spend = totalSpend;
                days = d.engineerDays;

                // Over-committing past the EUR 2.4M HQ funds is the "mechanism shopping" error — the
                // overspend buys no extra transfer and is penalised; only the affordable people-money
                // moves tacit know-how. Scale the productive people-spend down if you blew the budget.
                const affordableFactor = totalSpend > this.BUDGET_CAP ? this.BUDGET_CAP / totalSpend : 1;
                const productivePeople = peopleSpend * affordableFactor;
                transferDelta += productivePeople * 15;     // up to ~+24 when ~1.6M of people-money is affordable
                transferDelta += (docSpend * affordableFactor) * 1.5;  // documents help a little (explicit)
                if (totalSpend > this.BUDGET_CAP + 0.001) {
                    transferDelta -= 8; alignDelta -= 4; coachKey = `coach_r2_overbudget`;
                } else if (peopleSpend < 1.0) { coachKey = `coach_r2_docheavy`; }
                else if (peopleSpend >= 1.6) { coachKey = `coach_r2_people`; }

                // The digital twin SUPPORTS people but cannot replace them — diminishing/penalised
                // when it crowds out the people channel.
                if (d.digitaltwin >= 1.2 && peopleSpend < 1.0 && totalSpend <= this.BUDGET_CAP + 0.001) { transferDelta -= 6; coachKey = `coach_r2_twin`; }

                // Engineer-day discipline: the people channels need engineer time; over-booking the
                // 600-day pool (Common Error 2) commits engineers who do not exist.
                if (days > this.DAYS_CAP) {
                    transferDelta -= 10; alignDelta -= 3; ds.overDays = true; coachKey = `coach_r2_overdays`;
                } else if (peopleSpend >= 1.2 && days >= 250 && days <= this.DAYS_CAP) {
                    transferDelta += 6;                     // people money matched with real engineer time
                    alignDelta += 5;                        // a credibly prioritised, staffed people-led plan also reads as aligned to HQ
                } else if (peopleSpend >= 1.2 && days < 150) {
                    transferDelta -= 5; coachKey = `coach_r2_underdays`; // funded people channels, starved of engineers
                }

                // Inpatriate cohort: 3 is the sweet spot. 6 = heavy current-output loss; 0 = no tacit channel.
                if (d.inpatCount === 3) { transferDelta += 6; }
                else if (d.inpatCount === 1) { transferDelta += 1; }
                else if (d.inpatCount === 6) { transferDelta += 2; alignDelta -= 4; coachKey = `coach_r2_inpat6`; }
                else { transferDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_inpat0` : coachKey; } // 0

                const focused = (peopleSpend >= 1.4 && days <= this.DAYS_CAP && (d.inpatCount === 3 || d.inpatCount === 6));
                summaryKey = focused ? `sum_r2_good` : (ds.overDays ? `sum_r2_over` : `sum_r2_weak`);
            } else if (round === 3) {
                // Alignment (Kiessling) + absorptive capacity + retain the fragile channel + reintegration.
                // The absorptive-capacity build is an organisational/HR investment, separate from the
                // EUR 2.4M transfer-mechanism budget committed in Round 2 — it does not hit that cap.

                // Standardise / adapt: balanced is the alignment win; wholesale triggers family/board
                // resistance; over-localising forfeits HQ intent.
                if (d.standard === `balanced`) {
                    alignDelta += 20; transferDelta += 4; coachKey = `coach_r3_balanced`;
                } else if (d.standard === `wholesale`) {
                    alignDelta -= 12; transferDelta -= 4; coachKey = `coach_r3_wholesale`;
                } else { // local
                    alignDelta -= 8; coachKey = `coach_r3_local`;
                }

                // Absorptive capacity (Cohen & Levinthal): supervisors need a base to absorb lean systems.
                if (d.absorptive >= 0.2) { transferDelta += 9; alignDelta += 3; }
                else if (d.absorptive >= 0.1) { transferDelta += 4; }
                else { transferDelta -= 7; coachKey = (coachKey === `coach_default`) ? `coach_r3_noabsorb` : coachKey; }

                // Retain the at-risk engineer (the channel IS the people): a real role retains her;
                // salary-match only is fragile; ignoring loses an engineer and the supplier-quality channel.
                if (d.retention === `package`) {
                    transferDelta += 6; alignDelta += 2; coachKey = (d.standard === `balanced`) ? `coach_r3_retain` : coachKey;
                } else if (d.retention === `match`) {
                    transferDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_match` : coachKey;
                } else { // ignore -> lose her
                    engineerDelta -= 1; transferDelta -= 12; ds.channelLost = true; coachKey = `coach_r3_lostengineer`;
                }

                // Inpatriate reintegration: without a role waiting, absorbed knowledge walks out.
                if (d.reintegration >= 60) { transferDelta += 7; alignDelta += 2; }
                else if (d.reintegration <= 25) { transferDelta -= 8; coachKey = (coachKey === `coach_default` || coachKey === `coach_r3_balanced`) ? `coach_r3_noreintegration` : coachKey; }

                summaryKey = (d.standard === `balanced` && d.retention === `package` && d.reintegration >= 60) ? `sum_r3_good`
                    : (d.standard === `wholesale` ? `sum_r3_misalign` : `sum_r3_weak`);
            } else if (round === 4) {
                // Commit & defend: quarterly milestones + causal chain + staffable plan.
                if (d.milestones === `quarterly`) { alignDelta += 10; transferDelta += 4; coachKey = `coach_r4_quarterly`; }
                else if (d.milestones === `annual`) { alignDelta -= 2; coachKey = `coach_r4_annual`; }
                else { alignDelta -= 12; transferDelta -= 4; coachKey = `coach_r4_trust`; } // trust us

                if (d.logic === `causal`) { transferDelta += 8; alignDelta += 6; coachKey = (d.milestones === `quarterly`) ? `coach_r4_causal` : coachKey; }
                else if (d.logic === `financial`) { alignDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_financial` : coachKey; }
                else { transferDelta -= 4; alignDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_activity` : coachKey; } // activity list

                // Staffable without collapsing production: backfill protects line output.
                if (d.staffing === `protected`) { transferDelta += 6; alignDelta += 4; }
                else if (d.staffing === `optimistic`) { transferDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_optimistic` : coachKey; }
                else { transferDelta -= 9; alignDelta -= 4; coachKey = `coach_r4_overcommit`; } // overcommit

                alignDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.milestones === `quarterly` && d.logic === `causal` && d.staffing === `protected`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (budget reported in EUR to HQ; engineer days from the 600-day pool).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;
            ds.daysUsed = Math.round(ds.daysUsed + days);
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) ds.overBudget = true;
            if (ds.daysUsed > this.DAYS_CAP) ds.overDays = true;

            // Engineer channel.
            ds.engineers = Math.max(0, ds.engineers + engineerDelta);

            // Transfer effectiveness & strategic alignment move on their deltas (0–100, low start + headroom).
            ds.transfer = Math.max(0, Math.min(100, ds.transfer + transferDelta));
            ds.align = Math.max(0, Math.min(100, ds.align + alignDelta));

            // KIESSLING SPINE: subsidiary performance (convergence) rises only when transfer AND
            // alignment reinforce each other. Performance gain = small base + a strong interaction term
            // (geometric mean of transfer & alignment). Transfer without alignment, or alignment
            // without transfer, leaves convergence almost flat. A lost engineer caps the ceiling.
            const interaction = Math.sqrt(Math.max(0, ds.transfer) * Math.max(0, ds.align)) / 100; // 0..1
            let perfTarget = 4 + interaction * 96;                  // where perf is being pulled toward
            if (ds.channelLost) perfTarget -= 14;                   // fragile-channel collapse caps convergence
            if (ds.overBudget) perfTarget -= 8;                     // HQ funds convergence, not a shopping list
            const perfDelta = (perfTarget - ds.perf) * 0.55;        // ease toward the target each round
            ds.perf = Math.max(0, Math.min(100, ds.perf + perfDelta));

            ds.transferHistory.push(Math.round(ds.transfer));
            ds.alignHistory.push(Math.round(ds.align));
            ds.perfHistory.push(Math.round(ds.perf));

            if (round === this.ROUNDS.length && ds.perf < this.TARGET_PERF) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                transfer: Math.round(ds.transfer),
                transferDelta: Math.round(transferDelta),
                align: Math.round(ds.align),
                alignDelta: Math.round(alignDelta),
                perf: Math.round(ds.perf),
                perfDelta: Math.round(perfDelta),
                engineers: ds.engineers,
                budgetUsed: ds.budgetUsed,
                daysUsed: ds.daysUsed,
                channelLost: ds.channelLost,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

