            });
            uiManager.bind(`daysDisplay`, `domainState.daysUsed`, (v) => {
                const card = document.querySelector(`.knowhowsim-days-bar`);
                if (card) card.classList.toggle(`knowhowsim-days-over`, Number(v) > this.DAYS_CAP);
                return Math.round(Number(v)) + ` / 600`;
            });

            const self = this;

            // Diagnostic-candour slider readout.
            const can = document.getElementById(`candourInput`);
            const canReadout = document.getElementById(`candourReadout`);
            if (can && canReadout) {
                canReadout.textContent = can.value;
                can.addEventListener(`input`, function() { canReadout.textContent = can.value; });
            }

            // Reintegration slider readout.
            const rei = document.getElementById(`reintegrationInput`);
            const reiReadout = document.getElementById(`reintegrationReadout`);
            if (rei && reiReadout) {
                reiReadout.textContent = rei.value;
                rei.addEventListener(`input`, function() { reiReadout.textContent = rei.value; });
            }

            // Live budget-allocation total (Round 2).
            const allocIds = [`inpatriateInput`, `jointteamInput`, `codificationInput`, `digitaltwinInput`];
            const allocReadout = document.getElementById(`budgetAllocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (allocReadout) allocReadout.textContent = total.toFixed(2);
                // Over the EUR 2.4M HQ funds (or far past the 3.6M ceiling) reads red — the shopping error.
                const bar = document.querySelector(`.knowhowsim-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP + 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

