        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const transfer = Math.round(ds.transfer);
            const align = Math.round(ds.align);
            const perf = Math.round(ds.perf);

            const hitTarget = perf >= this.TARGET_PERF;
            const balanced = transfer >= 55 && align >= 55;
            const composite = Math.round(perf * 0.4 + transfer * 0.3 + align * 0.3);

            let performanceKey = `stalled`;
            if (perf >= this.GROUP_PERF && balanced) performanceKey = `full_convergence`;
            else if (hitTarget && balanced && composite >= 70) performanceKey = `demonstrable`;
            else if (hitTarget && balanced) performanceKey = `credible_trajectory`;
            else if (hitTarget) performanceKey = `hit_fragile`;
            else if (perf >= this.START_PERF + 20) performanceKey = `improving_short`;
            // Stable, language-independent tier handle for the grading/reporting layer (read from domainState).
            ds.performanceTier = performanceKey;
            // Localized label for the debrief overlay (fixes English label leaking on non-EN screens).
            const performance = window.mySimulation.t(`tier_` + performanceKey);

            const insights = [];
            if (hitTarget && balanced) insights.push(window.mySimulation.t(`insight_converged`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_fragile`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (transfer >= 55 && align < 45) insights.push(window.mySimulation.t(`insight_noalign`));
            if (align >= 55 && transfer < 45) insights.push(window.mySimulation.t(`insight_notransfer`));
            if (ds.channelLost) insights.push(window.mySimulation.t(`insight_channel`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (perf >= this.GROUP_PERF) insights.push(window.mySimulation.t(`insight_group`));

            return {
                transfer: transfer,
                align: align,
                perf: perf,
                engineers: ds.engineers,
                hitTarget: hitTarget,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.channelLost) return window.mySimulation.t(`hint_channel`);
            if (ds.overDays) return window.mySimulation.t(`hint_days`);
            if (ds.transfer >= 55 && ds.align < 40 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_align`);
            if (ds.transfer < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_transfer`);
            if (state.currentPeriod >= 3 && ds.perf < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.perf >= this.TARGET_PERF && ds.transfer >= 55 && ds.align >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

